ROT = ['EKMFLGDQVZNTOWYHXUSPAIBRCJ','AJDKSIRUXBLHWTMCQGZNPYFVOE','BDFHJLCPRTXVZNYEIWGAKMUSQO']
REF = 'YRUHQSLDPXNGOKMIEBFZCWVJAT'
CRIB = 'POLAND'
P=[[ord(c)-65 for c in R] for R in ROT]
INV=[[0]*26 for _ in range(3)]
for i in range(3):
    for c in range(26): INV[i][P[i][c]]=c
def step(o):
    o[0]=(o[0]+1)%26
    if o[0]==0:
        o[1]=(o[1]+1)%26
        if o[1]==0: o[2]=(o[2]+1)%26
def run(t,start):
    o=list(start); out=''
    for ch in t.upper():
        if not ch.isalpha(): out+=ch; continue
        step(o); x=ord(ch)-65
        for i in range(3): x=(P[i][(x+o[i])%26]-o[i])%26
        x=ord(REF[x])-65
        for i in reversed(range(3)): x=(INV[i][(x+o[i])%26]-o[i])%26
        out+=chr(x+65)
    return out
ct=open('cipher.txt').read().strip()
for a in range(26):
    for b in range(26):
        for c in range(26):
            pt=run(ct,[a,b,c])
            if CRIB in pt:
                print(pt.lower())
                raise SystemExit
